/**
 * Types for the nearhunt/project/1 record.
 *
 * Generated by hand from schema/nearhunt-project-1.schema.json — if you change one, change
 * both. `npm run validate:schema` checks that live on-chain records satisfy the schema.
 */

export const PROJECT_SCHEMA = 'nearhunt/project/1' as const;

export interface ProjectSource {
  /** Originating event or dataset, e.g. "nearhackathon-2026". */
  event: string;
  /** The source system's own id. Also the storage key suffix. */
  submission_id: string;
  /** Where a human can verify provenance. */
  url: string;
}

export interface ExternalCampaign {
  /** Hosting system, e.g. "babyshark". */
  provider: string;
  url: string;
  campaign_id?: string | null;
}

export interface ProjectLink {
  url: string;
  source_post_id?: string;
  /** NH-96 step 3: what the link is. */
  kind?: 'repository' | 'demo' | 'website' | 'video' | 'docs' | 'article' | 'explorer' | 'community';
  /** How `kind` was decided, strongest first: host, the builder's own words, the URL, default. */
  kind_basis?: 'host' | 'builder' | 'url' | 'default';
  /** Last visit (NH-96 step 2). `gone` = 404/410 or no such host; `unverified` = could not tell. */
  check?: { verdict: 'live' | 'gone' | 'unverified'; http_status: number | null; checked_at: string };
}

/**
 * One image from the builder's own X post. Referenced by URL on pbs.twimg.com, never copied.
 * A video is stored as its poster image; it plays on X (`post_url`), not on NEAR Hunt.
 */
export interface ProjectMedia {
  type: 'photo' | 'video';
  url: string;
  width?: number;
  height?: number;
  alt?: string | null;
  duration_ms?: number;
  post_url: string;
}

export interface Project {
  schema: typeof PROJECT_SCHEMA;
  /** `{source.event}:{source.submission_id}` */
  id: string;
  source: ProjectSource;
  name: string;
  /** Null means the source did not supply one — never treat as empty string. */
  description: string | null;
  tracks: string[];
  repository_url: string | null;
  demo_url: string | null;
  /** near.social discussion post, `{account_id}/{post_id}`. Absent until it exists. */
  social_post?: string | null;
  external_campaigns: ExternalCampaign[];
  /** Additive (NH-95): other URLs the builder posted on X. */
  links?: ProjectLink[] | null;
  /** Additive (NH-96): images and video posters attached to the builder's X post, by URL. */
  media?: ProjectMedia[] | null;
  /** ISO-8601 UTC, set by the importer. */
  updated_at: string;
}

/** A record as returned by the FastData KV read API. */
export interface KvEntry<T = unknown> {
  predecessor_id: string;
  current_account_id: string;
  block_height: number;
  /** Nanoseconds since epoch as an exact decimal string; the API's number exceeds 2^53. */
  block_timestamp: string;
  key: string;
  /** Null is a tombstone: the entity was deleted and this must be filtered out. */
  value: T | null;
}

/**
 * An upvote. Key `vote/{submission_id}` in the `nearhunt.near` namespace, written by the voter
 * (the voter is the row's `predecessor_id`). `{}` = active, `null` = withdrawn.
 */
export type Vote = Record<string, never>;

/** The list envelope used by the KV read API. */
export interface KvList<T = unknown> {
  entries: KvEntry<T>[];
  page_token?: string | null;
}
